WITH FilteredEmployees AS (SELECT * FROM employees WHERE dept_id IN (5, 11, 40)), summary AS (SELECT CASE WHEN job_title IN ('Manager', 'Director') THEN 'core' ELSE 'other' END AS job_title_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(level))) AS level_values, COUNT(DISTINCT salary) AS unique_depts FROM FilteredEmployees GROUP BY CASE WHEN job_title IN ('Manager', 'Director') THEN 'core' ELSE 'other' END) SELECT * FROM summary ORDER BY level_values ASC
